window.ECBA_QUESTION_BANK=window.ECBA_QUESTION_BANK||[];window.ECBA_QUESTION_BANK.push(...[{"id":"q687","domains":[5],"level":3,"tag":"Stakeholder","q":"Which guideline identifies approval authority and explains when approvals occur and how they align with organizational policies?","opts":["Solution Scope","Governance Approach","Change Strategy","Legal/Regulatory Information"],"answer":[1],"why":["Solution Scope supports assessment of alignment and completeness.","Correct: the Governance Approach identifies authority, responsibility, timing, and alignment with policies.","Change Strategy helps manage stakeholder consensus around needs.","Legal/Regulatory Information may affect approval, but does not define the full approval process."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q688","domains":[5],"level":4,"tag":"Stakeholder","q":"Which statement accurately describes the Sponsor’s role in approving requirements?","opts":["Reviews and approves the business case, solution or product scope, and requirements and designs","Provides opinions on how requirements relate to regulations","Ensures requirements and designs are supportable within technology standards and capability plans","Ensures business analysis information meets quality assurance and testability standards"],"answer":[0],"why":["Correct: these review and approval responsibilities are attributed to the Sponsor.","This describes the Regulator.","This describes Operational Support.","This describes the Tester."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q689","domains":[5],"level":5,"tag":"Stakeholder","q":"What do the outputs Requirements (approved) and Designs (approved) signify?","opts":["They are verified for sufficient quality but have not yet been agreed to","They are captured elicitation results awaiting confirmation","They are requirements and designs traced to components and releases","They are agreed to by stakeholders and ready for subsequent business analysis or solution development"],"answer":[3],"why":["Verification is a quality check before approval; it does not mean approval has occurred.","These are unconfirmed elicitation results.","This describes traced requirements and designs.","Correct: approved requirements and designs are agreed and ready for subsequent work."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98","multi":false,"sourceSet":"ecba-set-16.html"},{"id":"q690","domains":[5],"level":1,"tag":"Context","q":"What is the purpose of Plan Business Analysis Information Management?","opts":["Define how business analysis information will be stored, accessed, and used during and after a change","Define how business analysis activities will be selected and sequenced","Define how requirements will be approved by authorized stakeholders","Define how stakeholder roles and communication needs will be analyzed"],"answer":[0],"why":["Correct: the task establishes how BA information is managed throughout the change and beyond.","That is the purpose of Plan Business Analysis Approach.","That is addressed by Approve Requirements and governance.","That describes stakeholder engagement planning."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–47; BACCM™ Core Concept: Context","multi":false,"sourceSet":"ecba-set-17-context.html"},{"id":"q691","domains":[5],"level":2,"tag":"Context","q":"Which are inputs to Plan Business Analysis Information Management?","opts":["Requirements (approved)","Business Analysis Approach","Governance Approach","Stakeholder Engagement Approach"],"answer":[1,2,3],"why":["Approved requirements are not a listed input to this task.","Correct: the Business Analysis Approach informs information management planning.","Correct: Governance Approach informs storage, access, and management constraints.","Correct: Stakeholder Engagement Approach informs stakeholders’ information needs."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–47; BACCM™ Core Concept: Context","multi":true,"sourceSet":"ecba-set-17-context.html"},{"id":"q692","domains":[5],"level":3,"tag":"Context","q":"Which output describes the controls, storage, access, and organization of business analysis information?","opts":["Stakeholder Engagement Approach","Requirements Architecture","Information Management Approach","Business Analysis Approach"],"answer":[2],"why":["This addresses stakeholder engagement and communication.","This organizes requirements and their relationships.","Correct: the Information Management Approach defines how BA information is organized, stored, accessed, and maintained.","This defines the overall method for BA activities."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–47; BACCM™ Core Concept: Context","multi":false,"sourceSet":"ecba-set-17-context.html"},{"id":"q693","domains":[5],"level":4,"tag":"Context","q":"What is the purpose of Plan Business Analysis Approach?","opts":["Define the approach for storing and accessing business analysis information","Determine how solution limitations affect value","Establish how stakeholders will approve requirements","Define an appropriate method for conducting business analysis activities"],"answer":[3],"why":["That is the purpose of Plan Business Analysis Information Management.","That is the purpose of Assess Solution Limitations.","Approval authority and process are handled through governance and approval planning.","Correct: §3.1 defines the method for performing BA activities."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–31; BACCM™ Core Concept: Context","multi":false,"sourceSet":"ecba-set-17-context.html"},{"id":"q694","domains":[5],"level":5,"tag":"Context","q":"Which items can be identified in the Business Analysis Approach?","opts":["Business analysis activities and who will perform them","Timing and sequencing of the work","Deliverables and techniques that may be used","Requirements already approved for construction"],"answer":[0,1,2],"why":["Correct: the approach identifies activities and the people responsible.","Correct: timing and sequencing are part of the approach.","Correct: deliverables and techniques are identified.","Approved requirements are not defined by the approach output."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–31; BACCM™ Core Concept: Context","multi":true,"sourceSet":"ecba-set-17-context.html"},{"id":"q695","domains":[5],"level":1,"tag":"Context","q":"Which stakeholder roles are specifically listed for Plan Business Analysis Approach?","opts":["Regulator, Customer, Supplier, Implementation Subject Matter Expert","Domain Subject Matter Expert, Project Manager, Regulator, Sponsor","Domain Subject Matter Expert, Project Manager, Customer, Supplier","Sponsor, End User, Operational Support, Tester"],"answer":[1],"why":["This set does not match the roles listed for Plan Business Analysis Approach.","Correct: these are the four roles identified for this task.","This distractor substitutes Customer and Supplier for the specified Regulator and Sponsor.","This set combines roles that are associated with different business analysis tasks."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–31; BACCM™ Core Concept: Context","multi":false,"sourceSet":"ecba-set-17-context.html"},{"id":"q696","domains":[5],"level":2,"tag":"Context","q":"What is the purpose of Maintain Requirements?","opts":["Check requirements and designs against quality characteristics","Obtain approval of requirements and designs before further work","Keep requirements and designs accurate and consistent throughout their life cycle and support their reuse","Trace requirements to solution components to support impact analysis"],"answer":[2],"why":["That describes Verify Requirements.","That describes Approve Requirements.","Correct: maintenance preserves accuracy and consistency over time and enables reuse.","That describes Trace Requirements."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–86; BACCM™ Core Concept: Context","multi":false,"sourceSet":"ecba-set-17-context.html"},{"id":"q697","domains":[5],"level":3,"tag":"Context","q":"Which are inputs to Maintain Requirements?","opts":["Designs","Information Management Approach","Solution Performance Analysis","Requirements"],"answer":[0,3],"why":["Correct: Designs are also maintained.","Information Management Approach guides how information is stored and maintained, but BABOK lists it as a guideline/tool rather than an input to this task.","Solution Performance Analysis is not a listed input to this task.","Correct: Requirements may be maintained through their life cycle."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–86; BACCM™ Core Concept: Context","multi":true,"sourceSet":"ecba-set-17-context.html"},{"id":"q698","domains":[5],"level":4,"tag":"Context","q":"Which technique can help identify business rules that may be similar across an enterprise and reusable?","opts":["Business Rules Analysis","Data Flow Diagrams","Use Cases and Scenarios","Decision Analysis"],"answer":[0],"why":["Correct: Business Rules Analysis can reveal rules that may be reused across the enterprise.","Data Flow Diagrams represent information movement and boundaries.","Use Cases and Scenarios describe interactions and outcomes.","Decision Analysis evaluates choices but is not the named reuse technique here."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–86; BACCM™ Core Concept: Context","multi":false,"sourceSet":"ecba-set-17-context.html"},{"id":"q699","domains":[5],"level":5,"tag":"Context","q":"What is the purpose of Approve Requirements?","opts":["Maintain consistency and support reuse throughout the life cycle","Obtain agreement and approval on requirements and designs so work can proceed","Ensure requirements meet quality standards and are suitable for use","Ensure the requirements collectively support business objectives"],"answer":[1],"why":["That describes Maintain Requirements.","Correct: approval secures agreement and authorization to proceed.","That describes Verify Requirements.","That describes Define Requirements Architecture."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98; BACCM™ Core Concept: Context","multi":false,"sourceSet":"ecba-set-17-context.html"},{"id":"q700","domains":[5],"level":1,"tag":"Context","q":"Which are inputs to Approve Requirements?","opts":["Governance Approach","Elicitation Results (unconfirmed)","Requirements (verified)","Designs (verified)"],"answer":[2,3],"why":["Governance Approach identifies approval authority and process, but BABOK lists it as a guideline/tool, not an input.","Unconfirmed elicitation results are not ready for formal approval.","Correct: requirements should have been verified before approval.","Correct: verified designs are an input."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98; BACCM™ Core Concept: Context","multi":true,"sourceSet":"ecba-set-17-context.html"},{"id":"q701","domains":[5],"level":2,"tag":"Context","q":"Which role is responsible for ensuring requirements and designs are supportable within technology standards and organizational capability plans?","opts":["Sponsor","Regulator","Tester","Operational Support"],"answer":[3],"why":["The Sponsor focuses on business outcomes and authorization.","The Regulator provides regulatory perspectives and constraints.","The Tester considers quality assurance feasibility and testability.","Correct: Operational Support evaluates ongoing supportability within technology standards and capability plans."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98; BACCM™ Core Concept: Context","multi":false,"sourceSet":"ecba-set-17-context.html"},{"id":"q702","domains":[5],"level":3,"tag":"Context","q":"What is the purpose of Analyze Current State?","opts":["Understand why change is needed and what the change would affect","Define conditions that must be true for the desired future state","Determine which solution components prevent value realization","Measure whether a solution meets its performance targets"],"answer":[0],"why":["Correct: current-state analysis establishes the reasons and impacts of change.","That is the purpose of Define Future State.","That is Assess Solution Limitations.","That is Measure Solution Performance."],"ref":"BABOK Guide v3 §6.1 Analyze Current State, printed pp. 103–110; BACCM™ Core Concept: Context","multi":false,"sourceSet":"ecba-set-17-context.html"},{"id":"q703","domains":[5],"level":4,"tag":"Context","q":"Which are inputs to Analyze Current State?","opts":["Solution Recommendation","Needs","Elicitation Results","Business Analysis Approach"],"answer":[1,2],"why":["A Solution Recommendation is produced later, after potential solutions are analyzed.","Correct: Needs give rise to current-state analysis.","Correct: elicitation results provide information about the current state.","Business Analysis Approach guides the task but is not a listed input to Analyze Current State."],"ref":"BABOK Guide v3 §6.1 Analyze Current State, printed pp. 103–110; BACCM™ Core Concept: Context","multi":true,"sourceSet":"ecba-set-17-context.html"},{"id":"q704","domains":[5],"level":5,"tag":"Context","q":"Which outputs can result from Analyze Current State?","opts":["Solution Limitation","Requirements (maintained)","Current State Description","Business Requirements"],"answer":[2,3],"why":["Solution Limitation is an output of Assess Solution Limitations.","Requirements (maintained) is an output of Maintain Requirements.","Correct: the Current State Description records relevant enterprise context and capabilities.","Correct: Business Requirements express the problem, opportunity, or constraint."],"ref":"BABOK Guide v3 §6.1 Analyze Current State, printed pp. 103–110; BACCM™ Core Concept: Context","multi":true,"sourceSet":"ecba-set-17-context.html"},{"id":"q705","domains":[5],"level":1,"tag":"Context","q":"Which role may use an existing solution and provide information about issues with it?","opts":["Sponsor","Regulator","Project Manager","Customer"],"answer":[3],"why":["Sponsors may provide objectives and direction but are not the role specified here.","Regulators provide regulatory requirements and constraints.","Project Managers coordinate project work and plans.","Correct: Customers may use the existing solution and report issues."],"ref":"BABOK Guide v3 §6.1 Analyze Current State, printed pp. 103–110; BACCM™ Core Concept: Context","multi":false,"sourceSet":"ecba-set-17-context.html"},{"id":"q706","domains":[5],"level":2,"tag":"Context","q":"What is the purpose of Verify Requirements?","opts":["Ensure requirements and design specifications and models meet quality standards and are usable for their intended purpose","Ensure requirements and designs align with business goals and deliver stakeholder value","Confirm elicitation results are accurate and consistent","Obtain stakeholder agreement and formal approval"],"answer":[0],"why":["Correct: verification assesses quality and fitness for further use.","That describes Validate Requirements.","That describes Confirm Elicitation Results.","That describes Approve Requirements."],"ref":"BABOK Guide v3 §7.2 Verify Requirements, printed pp. 141–144; BACCM™ Core Concept: Context","multi":false,"sourceSet":"ecba-set-17-context.html"},{"id":"q707","domains":[5],"level":3,"tag":"Context","q":"Which are quality characteristics considered when verifying requirements and designs?","opts":["Unambiguous","Atomic","Complete","Consistent"],"answer":[0,1,2,3],"why":["Correct: unambiguous wording is a quality characteristic.","Correct: atomicity is a quality characteristic.","Correct: completeness is a quality characteristic.","Correct: consistency is a quality characteristic."],"ref":"BABOK Guide v3 §7.2 Verify Requirements, printed pp. 141–144; BACCM™ Core Concept: Context","multi":true,"sourceSet":"ecba-set-17-context.html"},{"id":"q708","domains":[5],"level":4,"tag":"Context","q":"Which input/output pairing is correct for Verify Requirements?","opts":["Elicitation Results (unconfirmed) is the only input; Elicitation Results (confirmed) is the output","Designs (maintained) is the input; Designs (approved) is the output","Requirements (any state) may be an input; Requirements (verified) is an output","Requirements (approved) is the only input; Requirements (validated) is the output"],"answer":[2],"why":["This describes the elicitation confirmation task.","Maintenance and approval are separate tasks.","Correct: requirements can be verified in different states; verified requirements are the task output.","Validation and approval are distinct tasks and outputs."],"ref":"BABOK Guide v3 §7.2 Verify Requirements, printed pp. 141–144; BACCM™ Core Concept: Context","multi":false,"sourceSet":"ecba-set-17-context.html"},{"id":"q709","domains":[5],"level":5,"tag":"Context","q":"What is the purpose of Define Requirements Architecture?","opts":["Ensure each requirement is individually clear and testable","Obtain approval from the appropriate stakeholder for each requirement","Determine how BA information will be stored and accessed","Ensure requirements collectively support one another to achieve business objectives"],"answer":[3],"why":["That is the focus of Verify Requirements.","That is the focus of Approve Requirements.","That is Plan Business Analysis Information Management.","Correct: architecture ensures the requirements as a whole support objectives."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–152; BACCM™ Core Concept: Context","multi":false,"sourceSet":"ecba-set-17-context.html"},{"id":"q710","domains":[5],"level":1,"tag":"Context","q":"Which are inputs to Define Requirements Architecture?","opts":["Requirements (any state)","Information Management Approach","Solution Scope","Business Analysis Performance Assessment"],"answer":[0,1,2],"why":["Correct: requirements in any state may be organized in the architecture.","Correct: this approach informs how architecture information is stored and accessed.","Correct: Solution Scope sets boundaries the architecture must respect.","Performance Assessment is not a listed input to this task."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–152; BACCM™ Core Concept: Context","multi":true,"sourceSet":"ecba-set-17-context.html"},{"id":"q711","domains":[5],"level":2,"tag":"Context","q":"Which technique can help organize and depict boundaries and relationships relevant to requirements architecture?","opts":["Survey or Questionnaire","Scope Modelling","Lessons Learned","Estimation"],"answer":[1],"why":["Surveys gather information from respondents.","Correct: Scope Modelling can depict boundaries and relationships relevant to architecture.","Lessons Learned supports reflection on past work.","Estimation forecasts effort, cost, or duration."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–152; BACCM™ Core Concept: Context","multi":false,"sourceSet":"ecba-set-17-context.html"},{"id":"q712","domains":[5],"level":3,"tag":"Context","q":"What is the purpose of Assess Solution Limitations?","opts":["Describe the enterprise’s current state and need for change","Assess whether requirements meet quality standards","Determine factors internal to a solution that restrict its full value realization","Determine factors external to a solution that restrict value realization"],"answer":[2],"why":["That is Analyze Current State.","That is Verify Requirements.","Correct: §8.3 examines internal solution factors that limit value.","That is Assess Enterprise Limitations."],"ref":"BABOK Guide v3 §8.3 Assess Solution Limitations, printed pp. 173–177; BACCM™ Core Concept: Context","multi":false,"sourceSet":"ecba-set-17-context.html"},{"id":"q713","domains":[5],"level":4,"tag":"Context","q":"Which are inputs to Assess Solution Limitations?","opts":["Solution Performance Analysis","Current State Description","Stakeholder Engagement Approach","Implemented Solution (external)"],"answer":[0,3],"why":["Correct: performance analysis helps identify limiting solution factors.","Current State Description is listed as an input to Assess Enterprise Limitations (§8.4), not Assess Solution Limitations (§8.3).","Stakeholder Engagement Approach is not a listed input to this task.","Correct: an external implemented solution can be assessed."],"ref":"BABOK Guide v3 §8.3 Assess Solution Limitations, printed pp. 173–177; BACCM™ Core Concept: Context","multi":true,"sourceSet":"ecba-set-17-context.html"},{"id":"q714","domains":[5],"level":5,"tag":"Context","q":"Which output captures factors within a solution that limit value realization?","opts":["Solution Limitation","Enterprise Limitation","Solution Performance Analysis","Business Requirements"],"answer":[0],"why":["Correct: Solution Limitation records the internal constraints or defects.","Enterprise Limitation captures factors external to the solution.","Solution Performance Analysis is an input to this assessment.","Business Requirements are identified through analysis of the need/current state."],"ref":"BABOK Guide v3 §8.3 Assess Solution Limitations, printed pp. 173–177; BACCM™ Core Concept: Context","multi":false,"sourceSet":"ecba-set-17-context.html"},{"id":"q715","domains":[5],"level":1,"tag":"Context","q":"Which considerations are included when assessing impacts of a solution limitation?","opts":["Only the cost of replacing the entire solution","Severity of the problem","Probability that the problem will recur","Impact on business operations and ability to absorb the impact"],"answer":[1,2,3],"why":["Assessment is not restricted to full replacement cost.","Correct: severity is considered.","Correct: likelihood of recurrence is considered.","Correct: operational impact and capacity to absorb it are considered."],"ref":"BABOK Guide v3 §8.3 Assess Solution Limitations, printed pp. 173–177; BACCM™ Core Concept: Context","multi":true,"sourceSet":"ecba-set-17-context.html"},{"id":"q716","domains":[5],"level":2,"tag":"Context","q":"What is the purpose of Assess Enterprise Limitations?","opts":["Measure solution performance against expectations","Define the approach for maintaining reusable requirements","Determine how factors external to the solution restrict value realization","Determine how internal solution components restrict value realization"],"answer":[2],"why":["That is Measure Solution Performance.","That is Maintain Requirements.","Correct: §8.4 examines factors outside the solution that constrain value.","That is Assess Solution Limitations."],"ref":"BABOK Guide v3 §8.4 Assess Enterprise Limitations, printed pp. 177–182; BACCM™ Core Concept: Context","multi":false,"sourceSet":"ecba-set-17-context.html"},{"id":"q717","domains":[5],"level":3,"tag":"Context","q":"Which factors may be considered when assessing enterprise limitations?","opts":["Organizational structure and capabilities","External dependencies and constraints","Solution interface defects only","Enterprise culture"],"answer":[0,1,3],"why":["Correct: organizational structure and capabilities are relevant enterprise factors.","Correct: external dependencies and constraints can limit realization of value.","Interface defects internal to a solution belong to solution limitation analysis.","Correct: enterprise culture may constrain a solution’s value."],"ref":"BABOK Guide v3 §8.4 Assess Enterprise Limitations, printed pp. 177–182; BACCM™ Core Concept: Context","multi":true,"sourceSet":"ecba-set-17-context.html"},{"id":"q718","domains":[5],"level":4,"tag":"Context","q":"How is enterprise culture characterized in the Enterprise Culture Assessment element?","opts":["Deeply rooted beliefs, values, and norms shared by members of an enterprise","Formal reporting relationships and organization charts only","Approved requirements and designs for the solution","External laws and regulations only"],"answer":[0],"why":["Correct: culture consists of deeply rooted shared beliefs, values, and norms.","Structure and charts may inform context but do not define culture.","These are business analysis information, not enterprise culture.","Regulations are external constraints, not the definition of culture."],"ref":"BABOK Guide v3 §8.4 Assess Enterprise Limitations, printed pp. 177–182; BACCM™ Core Concept: Context","multi":false,"sourceSet":"ecba-set-17-context.html"},{"id":"q719","domains":[5],"level":5,"tag":"Context","q":"Which output represents external-to-solution constraints affecting solution performance?","opts":["Requirements Architecture","Enterprise Limitation","Solution Limitation","Requirements (verified)"],"answer":[1],"why":["Requirements Architecture is produced by Define Requirements Architecture.","Correct: Enterprise Limitation captures the external factors and their effects.","Solution Limitation captures factors internal to the solution.","Verified requirements are an output of Verify Requirements."],"ref":"BABOK Guide v3 §8.4 Assess Enterprise Limitations, printed pp. 177–182; BACCM™ Core Concept: Context","multi":false,"sourceSet":"ecba-set-17-context.html"},{"id":"q720","domains":[5],"level":1,"tag":"Value","q":"What is the purpose of Plan Business Analysis Approach?","opts":["Define an appropriate method for conducting business analysis activities","Define how business analysis information will be stored and accessed","Plan an approach for establishing effective stakeholder relationships","Determine how the current solution restricts value realization"],"answer":[0],"why":["Correct: §3.1 defines the method for conducting business analysis activities.","This is the purpose of Plan Business Analysis Information Management.","This is the purpose of Plan Stakeholder Engagement.","This is the purpose of Assess Solution Limitations."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–31; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-17-value.html"},{"id":"q721","domains":[5],"level":2,"tag":"Value","q":"What does the Business Analysis Approach output identify?","opts":["Timing and sequencing of the work","Deliverables and techniques that may be used","Requirements approved for solution construction","Activities and who will perform them"],"answer":[0,1,3],"why":["Correct: timing and sequencing of work are included.","Correct: it identifies deliverables and business analysis techniques that may be used.","Approved requirements are an output of Approve Requirements.","Correct: the approach identifies the activities to be performed and who performs them."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–31; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-17-value.html"},{"id":"q722","domains":[5],"level":3,"tag":"Value","q":"Which stakeholder roles are specifically identified for Plan Business Analysis Approach?","opts":["Domain Subject Matter Expert, Regulator, Supplier, Sponsor","Project Manager, Customer, End User, Regulator","Domain Subject Matter Expert, Project Manager, Regulator, Sponsor","Domain Subject Matter Expert, Project Manager, Customer, Sponsor"],"answer":[2],"why":["Supplier is not one of the four roles listed for this task.","Customer and End User are not among the four roles listed for this task.","Correct: these four roles are specifically described in §3.1.7.","Customer is not one of the four roles listed for this task."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–31; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-17-value.html"},{"id":"q723","domains":[5],"level":5,"tag":"Value","q":"Which techniques are used to uncover information-management needs or improve the approach?","opts":["Brainstorming","Interviews","Lessons Learned","Acceptance and Evaluation Criteria"],"answer":[0,1,2],"why":["Correct: Brainstorming helps uncover stakeholder information-management needs.","Correct: Interviews help uncover individual stakeholders’ needs.","Correct: Lessons Learned supports analysis of efficient information-management approaches.","Acceptance and Evaluation Criteria is not listed as a technique for §3.4."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–47; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-17-value.html"},{"id":"q724","domains":[5],"level":1,"tag":"Value","q":"What output defines how business analysis information will be stored, accessed, and used during and after a change?","opts":["Business Analysis Approach","Requirements Architecture","Stakeholder Engagement Approach","Information Management Approach"],"answer":[3],"why":["The Business Analysis Approach defines the overall method for BA activities.","Requirements Architecture organizes requirements and their relationships.","Stakeholder Engagement Approach describes stakeholder relationships and collaboration.","Correct: the Information Management Approach defines storage, access, and use of BA information."],"ref":"BABOK Guide v3 §3.4 Plan Business Analysis Information Management, printed pp. 42–47; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-17-value.html"},{"id":"q725","domains":[5],"level":2,"tag":"Value","q":"What is the purpose of Maintain Requirements?","opts":["Ensure requirements meet quality standards and are usable for further work","Obtain agreement on requirements and designs before solution construction","Retain requirement accuracy and consistency through the requirements life cycle and support reuse","Preserve relationships between requirements and solution components for impact analysis"],"answer":[2],"why":["This describes Verify Requirements.","This describes Approve Requirements.","Correct: §5.2 retains accuracy and consistency and supports reuse in other solutions.","This describes Trace Requirements."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–86; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-17-value.html"},{"id":"q726","domains":[5],"level":3,"tag":"Value","q":"Which technique is used to identify business rules that may be similar across an enterprise to facilitate reuse?","opts":["Use Cases and Scenarios","Business Rules Analysis","Data Flow Diagrams","Data Modelling"],"answer":[1],"why":["Use Cases and Scenarios may support other analysis work but are not the described technique in this pairing.","Correct: Business Rules Analysis supports identifying similar business rules for reuse.","Data Flow Diagrams are used to identify reusable information flows.","Data Modelling is used to identify reusable data structures."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–86; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-17-value.html"},{"id":"q727","domains":[5],"level":4,"tag":"Value","q":"Which input/output relationships are correct for Maintain Requirements?","opts":["Requirements is an input","Designs is an input","Requirements (maintained) is an output","Designs (maintained) is an output"],"answer":[0,1,2,3],"why":["Correct: Requirements is an input.","Correct: Designs is an input.","Correct: Requirements (maintained) is an output.","Correct: Designs (maintained) is an output."],"ref":"BABOK Guide v3 §5.2 Maintain Requirements, printed pp. 83–86; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-17-value.html"},{"id":"q728","domains":[5],"level":5,"tag":"Value","q":"What is the purpose of Approve Requirements?","opts":["Check requirements and designs for accuracy and consistency with other information","Verify requirements are sufficiently clear, complete, and testable","Determine the implications of proposed changes to requirements and designs","Obtain agreement on and approval of requirements and designs so BA work or solution construction can proceed"],"answer":[3],"why":["This is Confirm Elicitation Results.","This is Verify Requirements.","This is Assess Requirements Changes.","Correct: this is the purpose of Approve Requirements."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-17-value.html"},{"id":"q729","domains":[5],"level":1,"tag":"Value","q":"Which input/output relationships are correct for Approve Requirements?","opts":["Requirements (approved) is an output","Designs (approved) is an output","Requirements (verified) is an input","Designs ready for further specification and development are an input"],"answer":[0,1,2,3],"why":["Correct: approved requirements are an output.","Correct: approved designs are an output.","Correct: verified requirements are an input.","Correct: designs ready for further specification and development are an input."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-17-value.html"},{"id":"q730","domains":[5],"level":2,"tag":"Value","q":"In Understand Stakeholder Roles, what must the business analyst know?","opts":["That every stakeholder has equal approval authority","Who has decision-making responsibility","Who has authority to sign off across the initiative","Which influential stakeholders should be consulted or informed"],"answer":[1,2,3],"why":["Only some stakeholders have authority to approve or deny changes.","Correct: the BA must identify who holds decision-making responsibility.","Correct: authority levels for sign-off must be understood.","Correct: influential stakeholders may need consultation or information."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-17-value.html"},{"id":"q731","domains":[5],"level":3,"tag":"Value","q":"Which stakeholder role is responsible for ensuring requirements and designs are supportable within technology standards and organizational capability plans?","opts":["Operational Support","Sponsor","Regulator","Tester"],"answer":[0],"why":["Correct: Operational Support addresses supportability within these constraints.","The Sponsor reviews and approves business case, scope, requirements, and designs.","The Regulator provides opinions on compliance with regulations.","The Tester considers quality assurance and testability."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-17-value.html"},{"id":"q732","domains":[5],"level":4,"tag":"Value","q":"What is the purpose of Analyze Current State?","opts":["Define the necessary conditions to meet a business need","Assess whether the solution meets its performance measures","Determine the internal factors restricting solution value","Understand why the enterprise needs to change and what the change would affect directly or indirectly"],"answer":[3],"why":["This is Define Future State.","This relates to measuring or analyzing solution performance.","This is Assess Solution Limitations.","Correct: §6.1 investigates why change is needed and what it would affect."],"ref":"BABOK Guide v3 §6.1 Analyze Current State, printed pp. 103–110; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-17-value.html"},{"id":"q733","domains":[5],"level":5,"tag":"Value","q":"Which are inputs to Analyze Current State?","opts":["Solution Recommendation","Requirements (approved)","Elicitation Results","Needs"],"answer":[2,3],"why":["Solution Recommendation is an output of Analyze Potential Value and Recommend Solution.","Approved requirements are not listed as an input to §6.1.","Correct: Elicitation Results help define and understand the current state.","Correct: the problem or opportunity often launches the analysis of current state."],"ref":"BABOK Guide v3 §6.1 Analyze Current State, printed pp. 103–110; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-17-value.html"},{"id":"q734","domains":[5],"level":1,"tag":"Value","q":"Which statements describe outputs of Analyze Current State?","opts":["Requirements (maintained) are made available for long-term organizational reuse","Current State Description provides context about scope, capabilities, resources, performance, and culture","Business Requirements define the problem, opportunity, or constraint based on understanding the current state","Solution Limitation describes internal constraints and defects in a solution"],"answer":[1,2],"why":["This is the output of Maintain Requirements.","Correct: the Current State Description captures enterprise context and related factors.","Correct: Business Requirements express the problem, opportunity, or constraint identified from current-state understanding.","This is the output of Assess Solution Limitations."],"ref":"BABOK Guide v3 §6.1 Analyze Current State, printed pp. 103–110; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-17-value.html"},{"id":"q735","domains":[5],"level":2,"tag":"Value","q":"Which stakeholder is described as using the existing solution and potentially providing input about issues with it?","opts":["Customer","Sponsor","Regulator","Project Manager"],"answer":[0],"why":["Correct: Customers use the existing solution and may provide input on current-solution issues.","Sponsors may provide needs and objectives but this is not the role description in §6.1.7.","Regulators provide compliance-related input.","Project Managers coordinate project work and schedules."],"ref":"BABOK Guide v3 §6.1 Analyze Current State, printed pp. 103–110; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-17-value.html"},{"id":"q736","domains":[5],"level":3,"tag":"Value","q":"What is the purpose of Verify Requirements?","opts":["Ensure requirements and designs align with business goals and deliver stakeholder value","Check elicitation information for accuracy and consistency","Obtain stakeholder agreement and approval of requirements","Ensure requirements and design specifications and models meet quality standards and are usable for their purpose"],"answer":[3],"why":["This is Validate Requirements.","This is Confirm Elicitation Results.","This is Approve Requirements.","Correct: verification checks quality standards and usability."],"ref":"BABOK Guide v3 §7.2 Verify Requirements, printed pp. 141–144; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-17-value.html"},{"id":"q737","domains":[5],"level":4,"tag":"Value","q":"Which are characteristics of acceptable-quality requirements and designs?","opts":["Consistent","Unambiguous","Atomic","Complete"],"answer":[0,1,2,3],"why":["Correct: consistency with stakeholder needs and other requirements is a quality characteristic.","Correct: unambiguous wording is a quality characteristic.","Correct: atomicity is a quality characteristic.","Correct: completeness is a quality characteristic."],"ref":"BABOK Guide v3 §7.2 Verify Requirements, printed pp. 141–144; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-17-value.html"},{"id":"q738","domains":[5],"level":5,"tag":"Value","q":"What is the output of Verify Requirements?","opts":["Elicitation Results (confirmed)","Requirements (verified)","Requirements (validated)","Requirements (approved)"],"answer":[1],"why":["Confirmed elicitation results are produced by Confirm Elicitation Results.","Correct: Requirements (verified) are of sufficient quality to serve as a basis for further work.","Validated requirements are produced by Validate Requirements.","Approved requirements are produced by Approve Requirements."],"ref":"BABOK Guide v3 §7.2 Verify Requirements, printed pp. 141–144; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-17-value.html"},{"id":"q739","domains":[5],"level":1,"tag":"Value","q":"What is the purpose of Define Requirements Architecture?","opts":["Ensure requirements collectively support one another to achieve the objectives","Ensure a single requirement is approved by the appropriate stakeholder","Ensure requirements are individually clear and testable","Establish how information will be stored and accessed"],"answer":[0],"why":["Correct: the architecture ensures the whole set of requirements supports the objectives.","This describes an approval decision.","This describes verification of individual requirement quality.","This is Plan Business Analysis Information Management."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–152; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-17-value.html"},{"id":"q740","domains":[5],"level":2,"tag":"Value","q":"Which are inputs to Define Requirements Architecture?","opts":["Requirements (any state)","Solution Scope","Design Options","Information Management Approach"],"answer":[0,1,3],"why":["Correct: requirements in any state are incorporated into the architecture.","Correct: Solution Scope sets boundaries with which the architecture must align.","Design Options are not listed as an input to this task.","Correct: Information Management Approach defines how requirements and models are stored and accessed."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–152; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-17-value.html"},{"id":"q741","domains":[5],"level":3,"tag":"Value","q":"Which statements about a requirements viewpoint and the Requirements Architecture output are correct?","opts":["Requirements Architecture may include recorded contextual information","A viewpoint is a single design option selected for implementation","A viewpoint defines conventions for representing, organizing, and relating requirements","Requirements Architecture includes requirements and their interrelationships"],"answer":[0,2,3],"why":["Correct: recorded contextual information may also be part of the architecture.","A viewpoint is not a design option.","Correct: a viewpoint defines requirements representation and organization conventions.","Correct: the output includes the requirements and interrelationships among them."],"ref":"BABOK Guide v3 §7.4 Define Requirements Architecture, printed pp. 148–152; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-17-value.html"},{"id":"q742","domains":[5],"level":4,"tag":"Value","q":"What is the purpose of Assess Solution Limitations?","opts":["Determine whether requirements and designs meet quality standards","Determine factors internal to the solution that restrict full value realization","Determine factors external to the solution that restrict value realization","Identify the problem or opportunity that defines business requirements"],"answer":[1],"why":["This is Verify Requirements.","Correct: §8.3 examines internal solution factors limiting value.","This is Assess Enterprise Limitations.","This is Analyze Current State."],"ref":"BABOK Guide v3 §8.3 Assess Solution Limitations, printed pp. 173–177; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-17-value.html"},{"id":"q743","domains":[5],"level":5,"tag":"Value","q":"Which are inputs and outputs for Assess Solution Limitations?","opts":["Implemented Solution (external) is an input","Solution Performance Analysis is an input","Solution Limitation is the output","Enterprise Limitation is the output"],"answer":[0,1,2],"why":["Correct: an implemented solution is an input to assess.","Correct: solution performance analysis informs the assessment.","Correct: Solution Limitation is the output.","Enterprise Limitation is the output of Assess Enterprise Limitations."],"ref":"BABOK Guide v3 §8.3 Assess Solution Limitations, printed pp. 173–177; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-17-value.html"},{"id":"q744","domains":[5],"level":1,"tag":"Value","q":"What does Impact Assessment consider when reviewing identified solution problems?","opts":["Probability that the problem will recur","Impact on business operations and capacity to absorb that impact","Only the cost of replacing the entire solution","Severity of the problem"],"answer":[0,1,3],"why":["Correct: probability of recurrence is considered.","Correct: operational impact and the enterprise’s capacity to absorb it are considered.","Assessment is broader than replacement cost and does not require replacing the entire solution.","Correct: severity is considered."],"ref":"BABOK Guide v3 §8.3 Assess Solution Limitations, printed pp. 173–177; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-17-value.html"},{"id":"q745","domains":[5],"level":2,"tag":"Value","q":"What is the purpose of Assess Enterprise Limitations?","opts":["Measure solution performance against value expectations","Define how requirements will be maintained for reuse","Determine how factors external to the solution restrict value realization","Determine the internal solution components that constrain performance"],"answer":[2],"why":["This is Measure Solution Performance or Analyze Performance Measures.","This is Maintain Requirements.","Correct: §8.4 identifies external-to-solution factors restricting value.","This is Assess Solution Limitations."],"ref":"BABOK Guide v3 §8.4 Assess Enterprise Limitations, printed pp. 177–182; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-17-value.html"},{"id":"q746","domains":[5],"level":3,"tag":"Value","q":"Which are inputs and outputs for Assess Enterprise Limitations?","opts":["Enterprise Limitation is the output","Current State Description is an input","Implemented or Constructed Solution (external) is an input","Solution Performance Analysis is an input"],"answer":[0,1,2,3],"why":["Correct: Enterprise Limitation describes the enterprise limits and their effect on solution performance.","Correct: the Current State Description gives context on environmental, cultural, and internal factors.","Correct: an implemented or constructed solution is assessed.","Correct: Solution Performance Analysis informs the limitations assessment."],"ref":"BABOK Guide v3 §8.4 Assess Enterprise Limitations, printed pp. 177–182; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-17-value.html"},{"id":"q747","domains":[5],"level":4,"tag":"Value","q":"How does BABOK define enterprise culture in the Enterprise Culture Assessment element?","opts":["Deeply rooted beliefs, values, and norms shared by members of an enterprise","Formal organization charts and reporting relationships only","The stated requirements and designs approved for the solution","The set of external regulations governing solution performance"],"answer":[0],"why":["Correct: this is the definition of enterprise culture in §8.4.4.","Organization charts and reporting structures may be considered but do not define culture.","These are business analysis work products, not enterprise culture.","Regulations may be an external factor but are not the definition of culture."],"ref":"BABOK Guide v3 §8.4 Assess Enterprise Limitations, printed pp. 177–182; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-17-value.html"},{"id":"q748","domains":[5],"level":5,"tag":"Value","q":"Which technique is used to identify organizational gaps or stakeholder concerns when assessing enterprise limitations?","opts":["Item Tracking","Data Modelling","Acceptance and Evaluation Criteria","Brainstorming"],"answer":[3],"why":["Item Tracking monitors and resolves identified issues.","Data Modelling represents data and its relationships.","Acceptance and Evaluation Criteria defines criteria for evaluating a solution or requirement.","Correct: Brainstorming can help identify organizational gaps or stakeholder concerns."],"ref":"BABOK Guide v3 §8.4 Assess Enterprise Limitations, printed pp. 177–182; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-17-value.html"},{"id":"q749","domains":[5],"level":1,"tag":"Stakeholder","q":"Which stakeholder characteristics are examined as part of stakeholder analysis?","opts":["Stakeholder roles","Stakeholder attitudes toward the change and collaboration","Decision-making authority","Whether the stakeholder has already approved all requirements"],"answer":[0,1,2],"why":["Correct: roles help identify where and how a stakeholder contributes.","Correct: attitudes can affect actions, behaviour, and engagement.","Correct: authority over activities, deliverables, and changes is analyzed.","Approval status is not a stakeholder characteristic identified in this element."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":true,"sourceSet":"ecba-set-17.html"},{"id":"q750","domains":[5],"level":2,"tag":"Stakeholder","q":"Which guidelines help assess stakeholder impact and understand the context of a desired change?","opts":["Current State Description","Elicitation Results (unconfirmed)","Requirements (approved)","Change Strategy"],"answer":[0,3],"why":["Correct: the Current State Description provides context for stakeholder analysis and understanding impact.","These results may inform other work but are not the two guidelines named here.","Approved requirements belong to the approval task and are not the stated guidelines.","Correct: Change Strategy supports stakeholder-impact assessment and engagement planning."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":true,"sourceSet":"ecba-set-17.html"},{"id":"q751","domains":[5],"level":3,"tag":"Stakeholder","q":"What does the Stakeholder Engagement Approach say about stakeholder roles?","opts":["It replaces the need to identify stakeholder characteristics","It records the final elicitation results for each stakeholder","It lists roles and responsibilities for the change","It records only who has formal approval authority"],"answer":[2],"why":["The output also includes analyzed characteristics and engagement approaches.","Elicitation results are a separate output of Conduct Elicitation.","Correct: the output includes a listing of stakeholder roles and responsibilities for the change.","Approval authority may be analyzed, but the output covers broader roles and responsibilities."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q752","domains":[5],"level":4,"tag":"Stakeholder","q":"Which technique is specifically used to identify potential stakeholders and help understand their relationships?","opts":["Survey or Questionnaire","Mind Mapping","Business Rules Analysis","Risk Analysis and Management"],"answer":[1],"why":["Surveys help identify shared characteristics within a stakeholder group.","Correct: Mind Mapping helps identify potential stakeholders and understand relationships among them.","Business Rules Analysis can identify stakeholders who were the source of business rules.","Risk Analysis and Management identifies risks arising from stakeholder attitudes or participation."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q753","domains":[5],"level":5,"tag":"Stakeholder","q":"Which role contributions are correctly matched when planning stakeholder engagement?","opts":["Sponsor: may request specific stakeholders be involved; Regulator: may require specific representatives or groups","Sponsor: source of external stakeholders; Regulator: source of internal stakeholders","Supplier: identifies approval authority; Customer: approves all requirements","End User: requests external stakeholder groups; Project Manager: establishes regulations"],"answer":[0],"why":["Correct: Sponsors may request stakeholder involvement; Regulators may require particular representatives or groups.","Customer and Supplier are sources of external stakeholders; End User is a source of internal stakeholders.","These responsibilities are not the described role contributions.","These descriptions do not match the stakeholder guidance."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q754","domains":[5],"level":1,"tag":"Stakeholder","q":"Which statement about the Project Manager’s role in stakeholder analysis is accurate?","opts":["Approves all stakeholder roles and communication methods","Is the only role responsible for stakeholder identification","Provides external regulatory requirements for stakeholder participation","May identify and recommend stakeholders; responsibility may be shared with the business analyst"],"answer":[3],"why":["Approval of roles and communication methods is not stated as the PM’s exclusive responsibility.","Stakeholder identification is not limited to the Project Manager.","This describes a Regulator’s potential influence.","Correct: the Project Manager may identify and recommend stakeholders, and responsibility may be shared with the BA."],"ref":"BABOK Guide v3 §3.2 Plan Stakeholder Engagement, printed pp. 31–36","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q755","domains":[5],"level":2,"tag":"Stakeholder","q":"Which statement best characterizes Conduct Elicitation?","opts":["It packages requirements for stakeholder understanding","It obtains formal agreement to proceed with solution construction","It draws out, explores, and identifies information relevant to the change","It turns elicitation results into confirmed information through accuracy checks"],"answer":[2],"why":["Communicate Business Analysis Information packages information for shared understanding.","Approve Requirements obtains agreement and approval.","Correct: elicitation draws out, explores, and identifies relevant information.","Confirm Elicitation Results checks accuracy and consistency."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q756","domains":[5],"level":3,"tag":"Stakeholder","q":"What does the Elicitation Activity Plan provide to the person conducting the activity?","opts":["Stakeholder approval authority and sign-off timing","Planned activities, techniques, logistics, scope, and available background sources","Approved requirements and designs ready for development","Confirmed elicitation results and their validation status"],"answer":[1],"why":["Approval roles and timing are addressed through governance.","Correct: the activity plan includes planned activities and techniques, logistics, scope, and background sources.","These are outputs of Approve Requirements.","Confirmed results come from Confirm Elicitation Results."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q757","domains":[5],"level":4,"tag":"Stakeholder","q":"Which are elements of guiding an elicitation activity?","opts":["Consider who provides the information","Consider who will use the information","Consider how the information will be used","Stop the activity only after formal requirements approval"],"answer":[0,1,2],"why":["Correct: the BA considers who provides information.","Correct: the intended users of the information help guide the activity.","Correct: intended use helps determine suitable outputs and when elicitation is sufficient.","The activity can end when sufficient elicitation has occurred; requirements approval is a separate task."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65","multi":true,"sourceSet":"ecba-set-17.html"},{"id":"q758","domains":[5],"level":5,"tag":"Stakeholder","q":"Which stakeholder is described as often guiding the business analyst to appropriate research sources and helping arrange research, experiments, or facilitated elicitation?","opts":["Customer","Sponsor","End User","Domain Subject Matter Expert"],"answer":[3],"why":["Customers provide valuable BA information during elicitation.","Sponsors authorize and ensure necessary stakeholders participate.","End Users should participate as users of existing and future solutions.","Correct: the Domain Subject Matter Expert may guide and assist with appropriate research sources and arrangements."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q759","domains":[5],"level":1,"tag":"Stakeholder","q":"Which outputs are correctly matched to their tasks?","opts":["Communicate Business Analysis Information—Business Analysis Information (communicated)","Conduct Elicitation—Stakeholder Engagement","Conduct Elicitation—Elicitation Results (unconfirmed)","Confirm Elicitation Results—Elicitation Results (confirmed)"],"answer":[0,2,3],"why":["Correct: Communicate Business Analysis Information produces communicated information.","Stakeholder Engagement is the output of Manage Stakeholder Collaboration.","Correct: Conduct Elicitation produces unconfirmed results.","Correct: Confirm Elicitation Results produces confirmed results."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65","multi":true,"sourceSet":"ecba-set-17.html"},{"id":"q760","domains":[5],"level":2,"tag":"Stakeholder","q":"Which guideline/tool helps shape questions and the elicitation approach using existing information?","opts":["Requirements (approved)","Existing Business Analysis Information","Governance Approach","Solution Scope"],"answer":[1],"why":["Approved requirements are not the named elicitation guideline here.","Correct: existing information may guide elicitation questions and how information is drawn out.","Governance Approach addresses decision-making and approval processes.","Solution Scope may be relevant context but is not the named guideline in this description."],"ref":"BABOK Guide v3 §4.2 Conduct Elicitation, printed pp. 61–65","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q761","domains":[5],"level":3,"tag":"Stakeholder","q":"When has the output Business Analysis Information (communicated) been achieved?","opts":["When target stakeholders understand the information’s content and implications","When the information has been sent to every stakeholder","When the business analyst has completed the package","When the information has received formal approval"],"answer":[0],"why":["Correct: communication is achieved when the target stakeholders understand content and implications.","Sending alone does not establish shared understanding.","Preparing a package is not sufficient if the target stakeholders do not understand it.","Approval may follow communication but is not the definition of communicated information."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q762","domains":[5],"level":4,"tag":"Stakeholder","q":"Which statements about communication package formats are accurate?","opts":["Informal documentation can be used during a change without being part of a formal organizational process","Presentations can provide high-level information to support understanding or decision-making","Presentations are the only acceptable format for communicating requirements","Formal documentation commonly uses an organizational template and can provide a stable long-term record"],"answer":[0,1,3],"why":["Correct: informal documentation may be used during a change without being part of a formal organizational process.","Correct: presentations can convey high-level information for understanding or decisions.","Requirements may be communicated in several package formats.","Correct: formal documentation is often template-based and supports a stable record."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71","multi":true,"sourceSet":"ecba-set-17.html"},{"id":"q763","domains":[5],"level":5,"tag":"Stakeholder","q":"Which input is defined as any kind of information, at any level of detail, used as an input or output of business analysis work?","opts":["Elicitation Activity Plan","Requirements Architecture","Business Analysis Information","Stakeholder Engagement Approach"],"answer":[2],"why":["This contains planned elicitation activities, logistics, scope, and background sources.","This organizes requirements and their relationships.","Correct: this is the BABOK definition of Business Analysis Information.","This describes stakeholder groups, roles, and communication needs."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q764","domains":[5],"level":1,"tag":"Stakeholder","q":"How do the two guidelines/tools differ for communicating business analysis information?","opts":["Business Analysis Approach defines solution scope; Information Management Approach prioritizes requirements","Business Analysis Approach describes how types of information are disseminated; Information Management Approach helps determine how information is packaged and communicated","Business Analysis Approach determines what is communicated; Information Management Approach determines stakeholder approval authority","Business Analysis Approach records elicitation results; Information Management Approach confirms their accuracy"],"answer":[1],"why":["These approaches do not define solution scope or requirement priorities.","Correct: the BA Approach describes dissemination characteristics, while the Information Management Approach informs packaging and communication.","Approval authority is addressed by governance; the BA Approach is about how information is disseminated rather than what.","These are not the purposes of the two approaches."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q765","domains":[5],"level":2,"tag":"Stakeholder","q":"Which statement distinguishes Reviews from Workshops as communication techniques?","opts":["Reviews can be used in group or individual collaboration; Workshops are typically used in group collaboration","Reviews are only individual; Workshops are only formal document distribution","Reviews define communication frequency; Workshops determine stakeholder authority","Reviews elicit information; Workshops approve requirements only"],"answer":[0],"why":["Correct: Reviews may be individual or group; Workshops are typically group collaboration.","Both techniques can support feedback; Workshops are not simply document distribution.","Communication frequency and approval authority are addressed elsewhere.","These techniques can support feedback, adjustments, consensus, and approvals rather than only the stated uses."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q766","domains":[5],"level":3,"tag":"Stakeholder","q":"Which stakeholder groups are specifically noted as needing frequent communication about relevant business analysis information?","opts":["Customers","Sponsors only","Regulators only","End Users"],"answer":[0,3],"why":["Correct: Customers also need frequent communication about relevant information.","Sponsors are not one of the two roles specifically named in §4.4.7.","Regulators are not one of the two roles specifically named in §4.4.7.","Correct: End Users need frequent communication about relevant information."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71","multi":true,"sourceSet":"ecba-set-17.html"},{"id":"q767","domains":[5],"level":4,"tag":"Stakeholder","q":"What is the output Stakeholder Engagement in Manage Stakeholder Collaboration?","opts":["A record of requirements and designs approved by stakeholder authorities","A plan of elicitation activities and supporting materials","Stakeholders’ willingness to engage in BA activities and interact with the business analyst when needed","A list of stakeholders, their analyzed characteristics, and the communication approach"],"answer":[2],"why":["These are outputs of Approve Requirements.","This is an Elicitation Activity Plan.","Correct: Stakeholder Engagement is willingness to participate and interact when necessary.","This is the Stakeholder Engagement Approach output of Plan Stakeholder Engagement."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–74","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q768","domains":[5],"level":5,"tag":"Stakeholder","q":"Which elements are included in Manage Stakeholder Collaboration?","opts":["Approve Requirements","Gain Agreement on Commitments","Monitor Stakeholder Engagement","Collaboration"],"answer":[1,2,3],"why":["Approval is a separate task, Approve Requirements.","Correct: gaining agreement on commitments is an element.","Correct: monitoring stakeholder engagement is an element.","Correct: collaboration is an element."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–74","multi":true,"sourceSet":"ecba-set-17.html"},{"id":"q769","domains":[5],"level":1,"tag":"Stakeholder","q":"What should be explicit when the business analyst and stakeholders agree on commitments?","opts":["Expectations and desired outcomes of the commitment","Final approval of all requirements","The solution’s acceptance criteria only","The stakeholder’s communication preference only"],"answer":[0],"why":["Correct: the commitment needs explicit understanding of expectations and desired outcomes.","Approval is not required to establish each commitment.","Acceptance criteria may be relevant elsewhere but are not the required commitment detail.","Communication preferences alone do not define the commitment."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–74","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q770","domains":[5],"level":2,"tag":"Stakeholder","q":"Which technique is matched correctly to its use in stakeholder collaboration?","opts":["Risk Analysis and Management—identify stakeholder role sources for business rules","Stakeholder List, Map, or Personas—approve requirements and designs","Collaborative Games—record formal stakeholder approval authority","Lessons Learned—understand stakeholder satisfaction or dissatisfaction and improve working relationships"],"answer":[3],"why":["Risk Analysis and Management focuses on risks to stakeholder involvement and engagement.","Stakeholder lists/maps/personas help determine who is available and who should be consulted.","Collaborative Games stimulate teamwork; governance defines approval authority.","Correct: Lessons Learned can reveal stakeholder satisfaction and help improve working relationships."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–74","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q771","domains":[5],"level":3,"tag":"Stakeholder","q":"Which statements describe collaboration in Manage Stakeholder Collaboration?","opts":["Collaboration supports shared effort to resolve problems and achieve desired outcomes","One-way updates replace dialogue and negotiation","Communication is regular, frequent, and bi-directional","Stakeholders should feel heard and recognize that their contributions matter"],"answer":[0,2,3],"why":["Correct: collaborative relationships support shared problem-solving and desired outcomes.","The BABOK describes two-way collaboration, not replacing it with one-way updates.","Correct: regular, frequent, bi-directional communication is part of collaboration.","Correct: stakeholder contributions should be heard and recognized."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–74","multi":true,"sourceSet":"ecba-set-17.html"},{"id":"q772","domains":[5],"level":4,"tag":"Stakeholder","q":"What is the role of Business Objectives as a guideline/tool for Manage Stakeholder Collaboration?","opts":["They list stakeholder attitudes and decision authority","They can focus diverse stakeholders on a common vision of desired business outcomes","They identify which requirements are ready for approval","They define how information will be stored and accessed"],"answer":[1],"why":["Attitudes and authority are analyzed during stakeholder analysis, not contained in Business Objectives.","Correct: Business Objectives can align stakeholders around the desired direction and outcomes.","Requirement approval readiness is handled in Approve Requirements.","Information storage and access are addressed by Information Management Approach."],"ref":"BABOK Guide v3 §4.5 Manage Stakeholder Collaboration, printed pp. 71–74","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q773","domains":[5],"level":5,"tag":"Stakeholder","q":"What does Requirements (verified), an input to Approve Requirements, represent?","opts":["Requirements verified to be of sufficient quality for reliable further specification and development","Requirements approved by stakeholders and ready for subsequent business analysis","Requirements elicited but not yet checked for accuracy","Requirements linked to solution components and releases"],"answer":[0],"why":["Correct: verified requirements are of sufficient quality to serve as reliable work for further specification and development.","This describes Requirements (approved), an output of the task.","This describes unconfirmed elicitation results.","This describes Requirements (traced)."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q774","domains":[5],"level":1,"tag":"Stakeholder","q":"What is the purpose of Conflict and Issue Management during approval?","opts":["Assign approval authority to every stakeholder who disagrees","Remove conflicting requirements without consulting stakeholders","Approve the requirement with the highest priority automatically","Facilitate communication so stakeholders understand one another’s needs and seek consensus before approval"],"answer":[3],"why":["Only some stakeholders hold approval authority.","Conflicts are managed through communication and resolution, not automatic removal.","Priority alone does not automatically determine approval.","Correct: the BA facilitates communication and seeks consensus to maintain support before requesting approval."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q775","domains":[5],"level":2,"tag":"Stakeholder","q":"Which statements correctly describe guidelines/tools used when approving requirements?","opts":["Solution Scope helps assess alignment and completeness","Stakeholder List, Map, or Personas defines formal approval criteria","Change Strategy can help manage consensus regarding stakeholder needs","Requirement Management Tools/Repository can record approvals"],"answer":[0,2,3],"why":["Correct: Solution Scope is considered to assess alignment and completeness.","Stakeholder List, Map, or Personas is a technique for stakeholder analysis, not the source of formal approval criteria.","Correct: Change Strategy supports managing consensus.","Correct: Requirement Management Tools/Repository may record approvals."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98","multi":true,"sourceSet":"ecba-set-17.html"},{"id":"q776","domains":[5],"level":3,"tag":"Stakeholder","q":"Which technique is specifically listed for Approve Requirements?","opts":["Decision Analysis","Acceptance and Evaluation Criteria","Reviews","Workshops"],"answer":[1],"why":["Decision Analysis is not the technique listed for Approve Requirements.","Correct: Acceptance and Evaluation Criteria is listed and used to define approval criteria.","Reviews are a technique for communicating information, not the listed §5.5 technique.","Workshops are used for communication and collaboration, not the listed approval technique."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q777","domains":[5],"level":4,"tag":"Stakeholder","q":"Which role is responsible for ensuring requirements and designs are supportable within technology standards and organizational capability plans?","opts":["Operational Support","Sponsor","Regulator","Tester"],"answer":[0],"why":["Correct: Operational Support is responsible for ensuring supportability within these constraints.","The Sponsor reviews and approves the business case, scope, requirements, and designs.","The Regulator provides opinions on requirements’ relationship to regulations.","The Tester considers quality assurance feasibility and testability."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98","multi":false,"sourceSet":"ecba-set-17.html"},{"id":"q778","domains":[5],"level":5,"tag":"Stakeholder","q":"Which outputs are produced by Approve Requirements?","opts":["Designs (approved)","Requirements (verified)","Designs (maintained)","Requirements (approved)"],"answer":[0,3],"why":["Correct: Designs (approved) is an output.","Requirements (verified) is an input to Approve Requirements.","Designs (maintained) is produced by Maintain Requirements.","Correct: Requirements (approved) is an output."],"ref":"BABOK Guide v3 §5.5 Approve Requirements, printed pp. 95–98","multi":true,"sourceSet":"ecba-set-17.html"},{"id":"q779","domains":[1],"level":1,"tag":"ALL","q":"How does the Business Analysis Standard define business analysis?","opts":["Enabling change by defining needs and recommending solutions that deliver value to stakeholders within a context","Managing projects by documenting requirements and delivering solutions within scope","Defining solutions by prioritizing stakeholder requests and approving designs","Enabling change by selecting technologies and measuring project outputs"],"answer":[0],"why":["Correct: this is the Standard’s definition.","Project management and documentation are not the full definition.","This narrows business analysis to solution selection and approval.","Technology selection and project outputs are not the definition."],"ref":"Business Analysis Standard v2 §2.1, printed p. 5","multi":false,"sourceSet":"ecba-set-18.html"},{"id":"q780","domains":[1],"level":2,"tag":"ALL","q":"Which concept is defined as a problem or opportunity to be addressed?","opts":["Solution","Need","Change","Value"],"answer":[1],"why":["A solution is a way to satisfy one or more needs.","Correct: the Standard defines a need as a problem or opportunity to be addressed.","Change is transformation in response to a need.","Value is worth, importance, or usefulness to a stakeholder."],"ref":"Business Analysis Standard v2 §2.1, printed p. 5","multi":false,"sourceSet":"ecba-set-18.html"},{"id":"q781","domains":[1],"level":3,"tag":"ALL","q":"Which pair is correctly matched to its Standard definition?","opts":["Need—act of transformation; Value—specific way of satisfying a need","Stakeholder—circumstances influencing change; Context—individual with a relationship to a solution","Change—act of transformation in response to a need; Solution—specific way of satisfying one or more needs in a context","Change—problem or opportunity; Solution—worth or usefulness to stakeholders"],"answer":[2],"why":["These definitions mismatch Change and Solution.","These definitions reverse Context and Stakeholder.","Correct: both definitions match the Standard.","These definitions belong to Need and Value, respectively."],"ref":"Business Analysis Standard v2 §2.1, printed p. 5","multi":false,"sourceSet":"ecba-set-18.html"},{"id":"q782","domains":[1],"level":4,"tag":"ALL","q":"Which statements describe how the BACCM is used?","opts":["To evaluate relationships among its six concepts","To replace task planning and stakeholder engagement","To consider quality and completeness of business analysis work","As a thinking and organizing model for effective business analysis"],"answer":[0,2,3],"why":["Correct: evaluating relationships among concepts is a stated use.","BACCM supports analysis; it does not replace tasks.","Correct: it helps evaluate the quality and completeness of work.","Correct: the Standard describes BACCM as a thinking and organizing model."],"ref":"Business Analysis Standard v2 §2.2, printed pp. 5–6","multi":true,"sourceSet":"ecba-set-18.html"},{"id":"q783","domains":[1],"level":5,"tag":"ALL","q":"Which core concept is the worth, importance, or usefulness of something to a stakeholder within a context?","opts":["Value","Need","Solution","Change"],"answer":[0],"why":["Correct: that is the Standard’s definition of Value.","A Need is a problem or opportunity.","A Solution is a way of satisfying needs.","Change is transformation in response to a need."],"ref":"Business Analysis Standard v2 §2.2, printed pp. 5–6","multi":false,"sourceSet":"ecba-set-18.html"},{"id":"q784","domains":[1],"level":1,"tag":"ALL","q":"Which statements about Context align with the Standard?","opts":["It influences, is influenced by, and helps explain the change","It includes circumstances relevant to a change","It may include culture, regulations, technology, and market trends","It is limited to the project schedule and budget"],"answer":[0,1,2],"why":["Correct: this captures the Standard’s definition.","Correct: relevant circumstances make up context.","Correct: these are examples of context.","Context is broader than schedule and budget."],"ref":"Business Analysis Standard v2 §2.3, printed p. 6","multi":true,"sourceSet":"ecba-set-18.html"},{"id":"q785","domains":[1],"level":2,"tag":"ALL","q":"Which stakeholder description matches the BACCM definition?","opts":["A group that directly uses an implemented solution","An individual accountable for defining business requirements","A group or individual with a relationship to the change, the need, or the solution","A person who approves requirements and controls project funding"],"answer":[2],"why":["End users are one stakeholder group, not the whole concept.","Business analysts may define requirements, but that is not stakeholder definition.","Correct: this is the BACCM stakeholder definition.","Some stakeholders may approve or fund, but this is not the definition."],"ref":"Business Analysis Standard v2 §2.2, printed pp. 5–6","multi":false,"sourceSet":"ecba-set-18.html"},{"id":"q786","domains":[3],"level":3,"tag":"ALL","q":"What distinguishes a predictive approach in the Business Analysis Standard?","opts":["It plans only the upcoming iteration and adapts from feedback","It delivers prioritized increments while minimizing upfront planning","It waits for a working solution before defining scope and cost","It plans work up front and tracks progress against the plan"],"answer":[3],"why":["That describes an adaptive approach.","Adaptive work prioritizes increments and limits upfront detail.","Predictive approaches typically establish plans and baselines before implementation.","Correct: the Standard describes predictive work as planned up front and tracked against the plan."],"ref":"Business Analysis Standard v2 §4.2, printed pp. 14–15","multi":false,"sourceSet":"ecba-set-18.html"},{"id":"q787","domains":[3],"level":4,"tag":"ALL","q":"Which characteristics are associated with an adaptive approach?","opts":["Prioritize high-value outcomes or deliverables","Plan upcoming iterations first","Create just-enough, just-in-time documentation","Define all work and baselines up front before implementation"],"answer":[0,1,2],"why":["Correct: adaptive work prioritizes value.","Correct: planning focuses first on upcoming iterations.","Correct: documentation is just enough and just in time.","This is characteristic of a predictive approach."],"ref":"Business Analysis Standard v2 §4.2, printed pp. 14–15","multi":true,"sourceSet":"ecba-set-18.html"}]);